 "content": "def transform(grid):
    # Decode left/top binary symbol panel as a 0/3 mask, preserving blank symbol 1.
    # Divider is the all-6 row/column when present; the resulting mask is the panel before it.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            panel = grid[:r]
            return [[3 if v == 1 else 1 for v in line] for line in panel]
    # On the 29x2 stream, the 0,0 row separates a 14-row pattern section;
    # its two symbols 8/1 decode as 3/1.
    return [[3 if v == 8 else 1 for v in row] for row in grid[:14]]

